0
];
// ATR value (price units)
error = EXIT_OK;
// No error
return
true
;
// Indicate success
}
The handle belongs to one symbol, so a position on another symbol is refused with EXIT_SYMBOL_MISMATCH. The initial stop is measured from the entry price. This keeps it consistent with the validator rule that an initial BUY stop lies below entry and an initial SELL stop above entry, no matter how far price has moved since the entry:
// --- Generate the initial stop proposal, anchored to the entry price
bool
GenerateProposal(SPositionSnapshot &position, SExitAdjustment &proposal, ENUM_EXIT_ERROR &error)
     {
// --- The cached handle belongs to m_symbol and must not be applied to another instrument
if
(position.symbol != m_symbol)
// Position is on another symbol
{
         error = EXIT_SYMBOL_MISMATCH;
// Set symbol mismatch error
return
false
;
// Return failure
}
double
atr;
// ATR value (price units)
if
(!GetClosedBarATR(atr, error))
// Read ATR of the last closed bar
return
false
;
// Return failure (error already set)
// --- ATR is already in price units, so it is not multiplied by _Point
double
distance = atr * m_multiplier_stop;
// Stop distance from entry (price units)
// --- Anchoring to entry keeps the stop valid for the initial-stop rule (BUY below, SELL above entry)
double
new_sl;
// New stop level (price units)
if
(position.direction ==
POSITION_TYPE_BUY
)
// Long position
new_sl = position.entry_price - distance;
// Stop below entry
else
// Short position
new_sl = position.entry_price + distance;
// Stop above entry
int
digits = ExitSymbolDigits(position.symbol);
// Digits of the position symbol
string
side = (position.direction ==
POSITION_TYPE_BUY
) ?
"-"
:
"+"
;
// Sign shown in the explanation
string
mult_text =
DoubleToString
(m_multiplier_stop,
2
);
// Multiplier as text
string
period_text =
IntegerToString
(m_atr_period);
// ATR period as text
string
sl_text =
DoubleToString
(new_sl, digits);
// Stop level as text
ZeroMemory
(proposal);
// Clear all fields
proposal.ticket = position.ticket;
// Set the ticket
proposal.action = EXIT_ACTION_STOP_MODIFICATION;
// Action: modify SL/TP
proposal.proposed_sl = new_sl;
// Proposed SL (price units)
proposal.proposed_tp = position.current_tp;
// Keep existing TP
proposal.close_volume =
0.0
;
// Stop modification carries no volume
proposal.reason = EXIT_REASON_ATR;
// Reason: ATR-based
proposal.explanation =
"ATR initial stop: entry "
+ side +
" "
+ mult_text;
// Explain the formula
proposal.explanation +=
" x ATR("
+ period_text +
") = "
+ sl_text;
// Explain the result
proposal.well_formed = (new_sl >
0
);
// A non-positive price is malformed
error = EXIT_OK;
// No error
return
true
;
// Indicate success
}
ATR is already expressed in price units. Multiplying it by _Point is a common mistake that turns a 0.0020 ATR into 0.00000002, so the code does not do it. For the same reason, the breakeven buffer and the trailing step, which are configured in points, are converted with the point of the position symbol (SYMBOL_POINT) rather than the chart's _Point.
The structure adjuster uses a pivot-based algorithm. It scans the last N closed bars for a price that is higher than its left and right neighbors (pivot high) or lower than both (pivot low). The lookback period, left strength, and right strength are configurable. If no pivot is found, it falls back to the lookback extreme. It produces a proposal only when the structural level lies on the loss side of entry and is tighter than the ATR stop. Otherwise it produces no proposal, because the ATR proposal already represents that stop.
Breakeven, trailing, and partial exit are R-based, so they have no meaning until 1R exists. The engine calls them only after a protective stop has been confirmed (PSF_INITIAL_STOP). Until then, only the two initial-stop modules and the time exit are evaluated, and the trace records why the other modules were skipped:
if
((pos.flags & PSF_INITIAL_STOP) ==
0
)
// No confirmed stop yet
{
// --- Only initial-stop modules run, R-based modules need 1R
if
(m_atr.GenerateProposal(pos, p, err))
// ATR initial stop
{
            Append(list, p);
// Append ATR proposal
double
atr_stop = p.proposed_sl;
// ATR stop passed explicitly
SExitAdjustment sp;
// Structure proposal
if
(m_structure.GenerateProposal(pos, atr_stop, sp, err))
// Structure stop if tighter
Append(list, sp);
// Append structure proposal
else
// No structure proposal
notes += ModuleNote(
"STRUCTURE"
, err);
// Report error, if any
}
else
// No ATR proposal
notes += ModuleNote(
"ATR"
, err);
// Report error
notes +=
"  - BREAKEVEN/TRAILING/PARTIAL: not evaluated (1R not established)\n"
;
// Explain skip
Each R-based module also refuses to work without 1R and returns EXIT_NO_INITIAL_RISK, so it is safe even when called directly, for example from a test.
The breakeven controller proposes a stop at entry plus a buffer (points) once the current R reaches its threshold. The trailing manager activates when the maximum favorable R reaches its threshold, and then trails the stop a fixed number of points behind price. The partial exit controller closes a fraction of the volume, rounded down to the volume step, once the maximum favorable R reaches its trigger. The time-exit controller proposes a full close when the position age exceeds the configured lifetime (minutes). These modules are deliberately simple; the subject of the article is how the engine chooses between them.
Deterministic Policy Resolution
All proposals are passed to CExitPolicyEngine. The policy engine does not pick a single winner. It returns all well-formed proposals in a strict total order, and the validator then works through that ranked list (next section). The order is defined by five keys; the first key that differs decides.
Key
PRECEDENCE_BY_REASON (default)
PRECEDENCE_BY_ACTION
1
Reason rank (index in the priority list)
Action rank (FULL_EXIT = 0, PARTIAL_EXIT = 1, STOP_MODIFICATION = 2)
2
Action rank
Reason rank
3
Reason enum value (orders reasons missing from the list)
Reason enum value
4
Stop modifications: tighter stop first. Partial exits: larger close volume (lots) first
Same
5
Explanation text, lexicographic
Same
Table 1. Ranking keys of the policy engine
The reason rank is the index of the reason in the configured priority list. The list has one slot per reason (EXIT_PRIORITY_SLOTS = 6), so every reason, including PARTIAL, can be ranked and no reason is silently ignored. A reason missing from the list receives the lowest rank, and ConfigWarnings() reports missing or duplicated entries when the engine starts. The demo EA fills all six slots:
void
SetDefaultPriority(SExitConfig &config)
  {
   config.priority[
0
] = EXIT_REASON_TIME;
// Highest priority: maximum lifetime
config.priority[
1
] = EXIT_REASON_PARTIAL;
// Second: scaling out
config.priority[
2
] = EXIT_REASON_BREAKEVEN;
// Third: protecting entry
config.priority[
3
] = EXIT_REASON_TRAILING;
// Fourth: trailing
config.priority[
4
] = EXIT_REASON_STRUCTURE;
// Fifth: initial stop from structure
config.priority[
5
] = EXIT_REASON_ATR;
// Lowest: initial stop from ATR
}
Precedence follows the strategy, not the action type. With the default PRECEDENCE_BY_REASON, a time exit wins over a breakeven move only because the configuration ranks TIME above BREAKEVEN. A full exit is not preferred simply because it closes the position. Until the close is executed and confirmed, it is only an intention, and a rejection, slippage, or a partial fill can leave risk open. A strategy that does want the most decisive action first can select PRECEDENCE_BY_ACTION explicitly; reason priority then only breaks ties within an action type.
// --- Order of two proposals: -1 = a first, +1 = b first, 0 = identical requests.
// --- Every key is a property of the proposal, so module call order cannot change the result.
int
Compare(SPositionSnapshot &pos, SExitAdjustment &a, SExitAdjustment &b)
     {
bool
by_reason = (m_mode == PRECEDENCE_BY_REASON);
// Selected ordering mode
int
ra = ReasonRank(a.reason);
// Reason rank of a
int
rb = ReasonRank(b.reason);
// Reason rank of b
int
aa = ActionRank(a.action);
// Action rank of a
int
ab = ActionRank(b.action);
// Action rank of b
int
k1a = by_reason ? ra : aa;
// Key 1 of a
int
k1b = by_reason ? rb : ab;
// Key 1 of b
int
k2a = by_reason ? aa : ra;
// Key 2 of a
int
k2b = by_reason ? ab : rb;
// Key 2 of b
if
(k1a != k1b)
// Key 1 decides
return
(k1a < k1b) ? -
1
:
1
;
// Lower rank first
if
(k2a != k2b)
// Key 2 decides
return
(k2a < k2b) ? -
1
:
1
;
// Lower rank first
if
(a.reason != b.reason)
// Key 3: reason value
return
((
int
)a.reason < (
int
)b.reason) ? -
1
:
1
;
// Orders reasons missing from the list
// --- From here both proposals have the same action
bool
stops = (a.action == EXIT_ACTION_STOP_MODIFICATION);
// Both are stop modifications
bool
partials = (a.action == EXIT_ACTION_PARTIAL_EXIT);
// Both are partial closes
if
(stops && a.proposed_sl != b.proposed_sl)
// Key 4 for stops
return
IsTighter(pos, a.proposed_sl, b.proposed_sl) ? -
1
:
1
;
// Tighter stop first
if
(partials && a.close_volume != b.close_volume)
// Key 4 for partials
return
(a.close_volume > b.close_volume) ? -
1
:
1
;
// Larger close volume first
int
s =
StringCompare
(a.explanation, b.explanation);
// Key 5: explanation text
if
(s !=
0
)
// Texts differ
return
(s <
0
) ? -
1
:
1
;
// Lexicographic order
return
0
;
// Identical requests
}
Every key is a property of the proposal itself. Changing the order in which the modules produce their proposals cannot change the ranking, and this is what makes the selection deterministic. Tests 8, 10, and 11 check it by ranking the same proposals in both input orders. Two proposals that are equal on all five keys are identical requests, so selecting either one leads to the same result.
Rank() sorts the proposals with an insertion sort into one pre-sized array. This is sufficient because the number of proposals is small and bounded (at most one per module per tick). Rank() also writes every candidate with its rank, and every malformed proposal that was dropped, into the decision trace:
// --- Rank all well-formed proposals and return their number; 'trace' lists every proposal
int
Rank(SPositionSnapshot &position, SExitAdjustment &adjustments[],
int
count, SExitAdjustment &ranked[],
string
&trace)
     {
ArrayResize
(ranked, count);
// Single allocation for all candidates
int
n =
0
;
// Number of ranked candidates
string
filtered =
""
;
// Dropped proposals (for the trace)
for
(
int
i =
0
; i < count; i++)
// Every input proposal
{
if
(!adjustments[i].well_formed)
// Malformed module output
{
            filtered +=
"  - "
+ Describe(position, adjustments[i]);
// Describe the proposal
filtered +=
" (not well-formed, dropped)\n"
;
// Mark it as dropped
continue
;
// Skip it
}
// --- Insertion sort: shift every candidate that must come after the new one
int
j = n;
// Insert position
while
(j >
0
&& Compare(position, adjustments[i], ranked[j-
1
]) <
0
)
// New one comes first
{
            ranked[j] = ranked[j-
1
];
// Shift right
j--;
// Move left
}
         ranked[j] = adjustments[i];
// Insert
n++;
// One more ranked candidate
}
ArrayResize
(ranked, n);
// Trim to the ranked count
string
mode = (m_mode == PRECEDENCE_BY_REASON) ?
"BY_REASON"
:
"BY_ACTION"
;
// Mode name
trace =
"Candidates ("
+
IntegerToString
(n) +
" ranked, mode "
+ mode +
"):\n"
;
// Section header
for
(
int
k =
0
; k < n; k++)
// One line per candidate
{
string
line = Describe(position, ranked[k]);
// Candidate description
trace +=
"  #"
+
IntegerToString
(k +
1
) +
" "
+ line +
"\n"
;
// Numbered candidate line
}
if
(n ==
0
)
// Nothing ranked
trace +=
"  (none)\n"
;
// Say so
trace += filtered;
// Append dropped proposals
return
n;
// Return ranked count
}
The policy engine does not validate broker rules. That is the job of the validator.
Broker-Aware Validation
CExitValidator checks one candidate at a time against risk invariants, broker constraints, and idempotency. The engine calls it for each ranked candidate in order and executes the first candidate that returns EXIT_RESULT_OK. A candidate that is rejected, or that would not change anything, does not stop the process; the next candidate is validated. Candidates ranked below the accepted one are not validated, and the trace says so. Validation therefore covers the selected candidate and every candidate ranked above it, not every proposal.
// --- Validate ranked candidates in order and return the index of the first that passes (-1 if none)
int
SelectFirstExecutable(SPositionSnapshot &pos, SExitAdjustment &ranked[],
int
n, SExitAdjustment &validated, ENUM_EXIT_RESULT &last_result,
string
&trace)
     {
      trace =
"Validation:\n"
;
// Section header
last_result = EXIT_RESULT_NO_EXECUTABLE_CANDIDATE;
// Default result
for
(
int
k =
0
; k < n; k++)
// Candidates in rank order
{
         SExitAdjustment v;
// Validated candidate
string
expl =
""
;
// Validator explanation
ENUM_EXIT_RESULT r = m_validator.Validate(pos, ranked[k], v, expl);
// Validate this candidate
string
name = ReasonName(ranked[k].reason) +
" "
+ ActionName(ranked[k].action);
// Candidate name
trace +=
"  #"
+
IntegerToString
(k +
1
) +
" "
+ name;
// Candidate number and name
trace +=
" -> "
+ ResultName(r) +
": "
+ expl +
"\n"
;
// Verdict
