IntegerToString
(n);
// Last skipped candidate
trace +=
"  #"
+ from_k +
"..#"
+ to_k +
" not validated\n"
;
// Note
}
return
k;
// Selected index
}
return
-
1
;
// No candidate passed
}
For a stop modification, the validator first normalizes the proposed stop to the tick size, so every later check sees the price that will actually be sent. It then applies the risk invariants. An initial stop (no current SL) must lie on the loss side of entry. An existing stop may only move in the direction that improves protection. The following table summarizes the direction rules:
Rule
Buy
Sell
Initial SL
SL < Entry
SL > Entry
Improve SL
New SL > Current SL
New SL < Current SL
1R (price units)
Entry - Initial SL
Initial SL - Entry
Current R
(Price - Entry) / 1R
(Entry - Price) / 1R
Breakeven
Entry + buffer (points x SYMBOL_POINT)
Entry - buffer (points x SYMBOL_POINT)
Table 2. Direction rules used by the validator and the R calculation
Idempotency prevents requests that would not change anything. If the position already has a stop and the normalized change is smaller than min_effective_sl_change (points), the result is EXIT_RESULT_NO_CHANGE and the next candidate is tried. Without an existing stop there is nothing to compare with. Repeated initial-stop requests are prevented by the pending mechanism described in State Reconciliation: no new request is sent for a position until the previous one is visible or a timeout expires.
// --- Idempotency: a change smaller than the threshold is not worth a request
if
(position.current_sl !=
0
)
// Existing stop present
{
double
cur = NormalizeToTickSize(position.symbol, position.current_sl);
// Existing stop on the grid
double
diff =
MathAbs
(sl - cur);
// Size of the change (price units)
if
(diff < m_config.min_effective_sl_change * point)
// Below threshold (points)
{
string
diff_text =
DoubleToString
(diff / point,
1
);
// Change as text (points)
explanation =
"SL change "
+ diff_text +
" points below threshold."
;
// Set explanation
return
EXIT_RESULT_NO_CHANGE;
// Nothing to do
}
        }
// --- Risk invariants: an initial stop sits on the loss side, an existing stop may only improve
bool
is_buy = (position.direction ==
POSITION_TYPE_BUY
);
// Direction of the position
if
(position.current_sl ==
0
)
// Initial stop
{
if
(is_buy && sl >= position.entry_price)
// BUY stop must be below entry
{
            explanation =
"Initial BUY stop must be below entry."
;
// Set explanation
return
EXIT_RESULT_INVALID_PRICE;
// Wrong side
}
if
(!is_buy && sl <= position.entry_price)
// SELL stop must be above entry
{
            explanation =
"Initial SELL stop must be above entry."
;
// Set explanation
return
EXIT_RESULT_INVALID_PRICE;
// Wrong side
}
        }
else
// Existing stop
{
bool
higher = (sl > position.current_sl);
// New stop above the current one
bool
lower = (sl < position.current_sl);
// New stop below the current one
bool
improves = is_buy ? higher : lower;
// Protection improves
if
(!improves)
// Stop would not improve
{
            explanation =
